let activeReceiptMeta = null;

function numberToWordsINR(num) {
  const a = ['', 'One ', 'Two ', 'Three ', 'Four ', 'Five ', 'Six ', 'Seven ', 'Eight ', 'Nine ', 'Ten ', 'Eleven ', 'Twelve ', 'Thirteen ', 'Fourteen ', 'Fifteen ', 'Sixteen ', 'Seventeen ', 'Eighteen ', 'Nineteen '];
  const b = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];

  if ((num = num.toString()).length > 9) return 'overflow';
  const n = ('000000000' + num).substr(-9).match(/^(\d{2})(\d{2})(\d{2})(\d{1})(\d{2})$/);
  if (!n) return '';
  let str = '';
  str += (n[1] != 0) ? (a[Number(n[1])] || b[n[1][0]] + ' ' + a[n[1][1]]) + 'Crore ' : '';
  str += (n[2] != 0) ? (a[Number(n[2])] || b[n[2][0]] + ' ' + a[n[2][1]]) + 'Lakh ' : '';
  str += (n[3] != 0) ? (a[Number(n[3])] || b[n[3][0]] + ' ' + a[n[3][1]]) + 'Thousand ' : '';
  str += (n[4] != 0) ? (a[Number(n[4])] || b[n[4][0]] + ' ' + a[n[4][1]]) + 'Hundred ' : '';
  str += (n[5] != 0) ? ((str != '') ? 'and ' : '') + (a[Number(n[5])] || b[n[5][0]] + ' ' + a[n[5][1]]) : '';
  return str.trim() + ' Only';
}

// ==========================================================================
// 3. MATHEMATICAL CALCULATION ENGINES (ROLE-AWARE)
// ==========================================================================
function calculateOverallAttendance() {
  const isStaff = AcademicStore.student.role === 'faculty';

  if (isStaff) {
    const list = FacultyStore.students;
    const total = list.length || 1;
    let totAttPct = 0;
    let eligibleCount = 0;

    list.forEach(s => {
      totAttPct += s.attendance_pct;
      if (s.attendance_pct >= 75.0) eligibleCount++;
    });

    const avgPercent = parseFloat((totAttPct / total).toFixed(1));
    const shortageCount = total - eligibleCount;

    return {
      percentage: avgPercent,
      totalConducted: total * 250,
      totalAttended: Math.round((total * 250) * (avgPercent / 100)),
      safetyMargin: eligibleCount,
      isEligible: avgPercent >= 75.0,
      status: `${eligibleCount}/${total} Students Above 75% Threshold ✓`,
      shortageCount: shortageCount,
      eligibleCount: eligibleCount
    };
  }

  // Student calculation
  let totalConducted = 0;
  let totalAttended = 0;

  AcademicStore.courses.forEach(c => {
    totalConducted += c.conducted;
    totalAttended += c.attended;
  });

  const percent = totalConducted > 0 ? (totalAttended / totalConducted) * 100 : 0;
  const thresholdClasses = Math.ceil(totalConducted * 0.75);
  const safetyMargin = totalAttended - thresholdClasses;

  return {
    percentage: parseFloat(percent.toFixed(1)),
    totalConducted,
    totalAttended,
    safetyMargin,
    isEligible: percent >= 75.0,
    status: percent >= 75.0 ? 'Eligible for Examinations ✓' : (percent >= 65.0 ? 'Warning (Condonation)' : 'Critical Shortage')
  };
}

function calculateCGPA() {
  const isStaff = AcademicStore.student.role === 'faculty';

  if (isStaff) {
    const list = FacultyStore.students;
    const total = list.length || 1;
    let totCgpa = 0;

    list.forEach(s => {
      totCgpa += s.cgpa;
    });

    const avgCgpa = parseFloat((totCgpa / total).toFixed(2));
    const classification = getGradeClassification(avgCgpa);
    classification.label = `Grade: ${classification.letter} (Class Average: ${avgCgpa.toFixed(2)})`;

    return {
      cgpa: avgCgpa,
      totalCredits: 19 * total,
      classification: classification
    };
  }

  // Student calculation
  let totalGradePoints = 0;
  let totalCredits = 0;

  AcademicStore.courses.forEach(c => {
    totalGradePoints += c.credits * c.gradePoint;
    totalCredits += c.credits;
  });

  const cgpa = totalCredits > 0 ? (totalGradePoints / totalCredits) : 0;
  return {
    cgpa: parseFloat(cgpa.toFixed(2)),
    totalCredits,
    classification: getGradeClassification(cgpa)
  };
}

function getGradeClassification(cgpa) {
  if (cgpa >= 9.0) return { label: 'Grade: O (Outstanding)', class: 'grade-o', letter: 'O' };
  if (cgpa >= 8.0) return { label: 'Grade: A+ (Excellent)', class: 'grade-aplus', letter: 'A+' };
  if (cgpa >= 7.0) return { label: 'Grade: A (Very Good)', class: 'grade-a', letter: 'A' };
  if (cgpa >= 6.0) return { label: 'Grade: B+ (Good)', class: 'grade-bplus', letter: 'B+' };
  return { label: 'Grade: B (Average)', class: 'grade-b', letter: 'B' };
}

