function openStaffEvalModal(studentRoll = null) {
  const modal = document.getElementById('modal-staff-eval');
  if (!modal) return;

  let targetRoll = studentRoll || FacultyStore.selectedStudentRoll || '711522104001';
  let studentObj = FacultyStore.students.find(s => s.roll_no === targetRoll) || FacultyStore.students[0];
  FacultyStore.selectedStudentRoll = studentObj.roll_no;

  const subEl = document.getElementById('staff-eval-subtitle');
  if (subEl) {
    subEl.textContent = `Student: ${studentObj.name} (Reg No: ${studentObj.roll_no}) — ${studentObj.dept}`;
  }

  const feeSelect = document.getElementById('staff-eval-fee-select');
  if (feeSelect) feeSelect.value = studentObj.fee_status || 'Paid';

  const cgpaInp = document.getElementById('staff-eval-cgpa-input');
  if (cgpaInp) cgpaInp.value = studentObj.cgpa.toFixed(2);

  const attInp = document.getElementById('staff-eval-att-input');
  if (attInp) attInp.value = studentObj.attendance_pct.toFixed(1);

  const tbody = document.getElementById('tbody-staff-eval');
  if (!tbody) return;

  tbody.innerHTML = AcademicStore.courses.map((c, idx) => {
    return `
      <tr>
        <td><strong>${c.code}</strong><br><small style="color: #64748b;">${c.title}</small></td>
        <td>
          <input type="number" id="staff-att-${idx}" value="${c.attended}" min="0" max="${c.conducted}" style="width: 55px; padding: 4px; border: 1px solid #cbd5e1; border-radius: 4px;">
          / ${c.conducted}
        </td>
        <td><input type="number" id="staff-t1-${idx}" value="${c.test1}" min="0" max="25" style="width: 50px; padding: 4px; border: 1px solid #cbd5e1; border-radius: 4px;" oninput="recalcModalRow(${idx})"></td>
        <td><input type="number" id="staff-t2-${idx}" value="${c.test2}" min="0" max="25" style="width: 50px; padding: 4px; border: 1px solid #cbd5e1; border-radius: 4px;" oninput="recalcModalRow(${idx})"></td>
        <td><input type="number" id="staff-model-${idx}" value="${c.model}" min="0" max="50" style="width: 50px; padding: 4px; border: 1px solid #cbd5e1; border-radius: 4px;" oninput="recalcModalRow(${idx})"></td>
        <td><input type="number" id="staff-assign-${idx}" value="${c.assign}" min="0" max="10" style="width: 50px; padding: 4px; border: 1px solid #cbd5e1; border-radius: 4px;" oninput="recalcModalRow(${idx})"></td>
        <td><strong id="staff-total-${idx}">${c.total}</strong></td>
      </tr>
    `;
  }).join('');

  modal.classList.add('active');
}

function recalcModalRow(idx) {
  const t1 = Math.min(25, Math.max(0, parseInt(document.getElementById(`staff-t1-${idx}`)?.value) || 0));
  const t2 = Math.min(25, Math.max(0, parseInt(document.getElementById(`staff-t2-${idx}`)?.value) || 0));
  const model = Math.min(50, Math.max(0, parseInt(document.getElementById(`staff-model-${idx}`)?.value) || 0));
  const assign = Math.min(10, Math.max(0, parseInt(document.getElementById(`staff-assign-${idx}`)?.value) || 0));

  const total = Math.min(100, t1 + t2 + Math.round(model * 0.8) + assign);
  const totEl = document.getElementById(`staff-total-${idx}`);
  if (totEl) totEl.textContent = total;
}

function closeStaffEvalModal() {
  const modal = document.getElementById('modal-staff-eval');
  if (modal) modal.classList.remove('active');
}

async function saveStaffEvaluation() {
  const roll = FacultyStore.selectedStudentRoll || '711522104001';
  const feeSelect = document.getElementById('staff-eval-fee-select');
  const newFeeStatus = feeSelect ? feeSelect.value : 'Paid';

  const cgpaInp = document.getElementById('staff-eval-cgpa-input');
  const attInp = document.getElementById('staff-eval-att-input');

  let totalPoints = 0;
  let totalCredits = 0;
  let totalAttended = 0;
  let totalConducted = 0;

  AcademicStore.courses.forEach((c, idx) => {
    const sAtt = document.getElementById(`staff-att-${idx}`);
    const t1Inp = document.getElementById(`staff-t1-${idx}`);
    const t2Inp = document.getElementById(`staff-t2-${idx}`);
    const modelInp = document.getElementById(`staff-model-${idx}`);
    const assignInp = document.getElementById(`staff-assign-${idx}`);

    if (sAtt) c.attended = Math.min(c.conducted, Math.max(0, parseInt(sAtt.value) || 0));
    if (t1Inp) c.test1 = Math.min(25, Math.max(0, parseInt(t1Inp.value) || 0));
    if (t2Inp) c.test2 = Math.min(25, Math.max(0, parseInt(t2Inp.value) || 0));
    if (modelInp) c.model = Math.min(50, Math.max(0, parseInt(modelInp.value) || 0));
    if (assignInp) c.assign = Math.min(10, Math.max(0, parseInt(assignInp.value) || 0));

    c.total = c.test1 + c.test2 + Math.round(c.model * 0.8) + c.assign;
    c.total = Math.min(100, c.total);

    if (c.total >= 90) { c.grade = 'O'; c.gradePoint = 10; }
    else if (c.total >= 80) { c.grade = 'A+'; c.gradePoint = 9; }
    else if (c.total >= 70) { c.grade = 'A'; c.gradePoint = 8; }
    else if (c.total >= 60) { c.grade = 'B+'; c.gradePoint = 7; }
    else { c.grade = 'B'; c.gradePoint = 6; }

    totalPoints += c.credits * c.gradePoint;
    totalCredits += c.credits;
    totalAttended += c.attended;
    totalConducted += c.conducted;
  });

  let updatedCgpa = parseFloat((totalPoints / (totalCredits || 1)).toFixed(2));
  let updatedAttPct = parseFloat(((totalAttended / (totalConducted || 1)) * 100).toFixed(1));

  if (cgpaInp && cgpaInp.value) {
    updatedCgpa = parseFloat(Math.min(10, Math.max(0, parseFloat(cgpaInp.value))).toFixed(2));
  }
  if (attInp && attInp.value) {
    updatedAttPct = parseFloat(Math.min(100, Math.max(0, parseFloat(attInp.value))).toFixed(1));
  }

  const stu = FacultyStore.students.find(s => s.roll_no === roll);
  if (stu) {
    stu.fee_status = newFeeStatus;
    stu.cgpa = updatedCgpa;
    stu.attendance_pct = updatedAttPct;
  }

  try {
    await fetch('/api/faculty/update-student', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        roll_no: roll,
        courses: AcademicStore.courses,
        fee_status: newFeeStatus,
        cgpa: updatedCgpa,
        attendance_pct: updatedAttPct
      })
    });
  } catch (e) {}

  updateDashboardUI();
  renderFacultyRoster();
  closeStaffEvalModal();
  showToast(`Evaluation, CGPA & Fee Status updated for ${stu ? stu.name : roll}! 🎓`, 'success', 3500);

  if (window.monsterEngine && typeof window.monsterEngine.celebrate === 'function') {
    window.monsterEngine.celebrate();
  }
}

