async function submitFacultyAddStudent() {
  const rollVal = document.getElementById('add-stu-roll')?.value.trim();
  const nameVal = document.getElementById('add-stu-name')?.value.trim();
  const deptVal = document.getElementById('add-stu-dept')?.value;
  const emailVal = document.getElementById('add-stu-email')?.value.trim() || `student${FacultyStore.students.length + 1}@nexdemy.edu`;
  const mobileVal = document.getElementById('add-stu-mobile')?.value.trim() || '+91 9876543200';
  const cgpaVal = parseFloat(document.getElementById('add-stu-cgpa')?.value) || 8.5;
  const attVal = parseFloat(document.getElementById('add-stu-att')?.value) || 85.0;
  const feeVal = document.getElementById('add-stu-fee')?.value || 'Paid';

  if (!rollVal || rollVal.length !== 12 || !/^\d{12}$/.test(rollVal)) {
    showToast('Register Number must be exactly 12 digits.', 'warning');
    return;
  }

  if (!nameVal) {
    showToast('Please enter the student full name.', 'warning');
    return;
  }

  const existing = FacultyStore.students.find(s => s.roll_no === rollVal);
  if (existing) {
    showToast(`Register Number ${rollVal} already exists in class roster.`, 'warning');
    return;
  }

  const newStudent = {
    name: nameVal,
    roll_no: rollVal,
    dept: deptVal,
    email: emailVal,
    mobile: mobileVal,
    fee_status: feeVal,
    attendance_pct: attVal,
    cgpa: cgpaVal
  };

  FacultyStore.students.push(newStudent);

  try {
    await fetch('/api/faculty/add-student', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(newStudent)
    });
  } catch (e) {}

  updateDashboardUI();
  renderFacultyRoster();
  closeAddStudentModal();
  showToast(`Student ${nameVal} (${rollVal}) successfully added to class roster! 🎓`, 'success', 4000);

  if (window.monsterEngine && typeof window.monsterEngine.celebrate === 'function') {
    window.monsterEngine.celebrate();
  }
}

