function openEditProfileModal() {
  const s = AcademicStore.student;
  const modal = document.getElementById('modal-edit-profile');
  if (!modal) return;

  const editName = document.getElementById('edit-name');
  const editRoll = document.getElementById('edit-roll');
  const editDept = document.getElementById('edit-dept');
  const editEmail = document.getElementById('edit-email');
  const editMobile = document.getElementById('edit-mobile');

  if (editName) editName.value = s.name;
  if (editRoll) editRoll.value = s.roll_no;
  if (editDept) editDept.value = s.dept;
  if (editEmail) editEmail.value = s.email;
  if (editMobile) editMobile.value = s.mobile;

  modal.classList.add('active');
  modal.style.display = 'flex';
}

function closeEditProfileModal() {
  const modal = document.getElementById('modal-edit-profile');
  if (modal) {
    modal.classList.remove('active');
    modal.style.display = 'none';
  }
}

async function saveProfileChanges() {
  const nameVal = document.getElementById('edit-name')?.value.trim();
  const rollVal = document.getElementById('edit-roll')?.value.trim();
  const deptVal = document.getElementById('edit-dept')?.value;
  const emailVal = document.getElementById('edit-email')?.value.trim();
  const mobileVal = document.getElementById('edit-mobile')?.value.trim();

  if (rollVal && rollVal.length !== 12 && !rollVal.startsWith('STAFF')) {
    showToast('Register Number must be exactly 12 digits.', 'warning');
    return;
  }

  if (nameVal) AcademicStore.student.name = nameVal;
  if (rollVal) AcademicStore.student.roll_no = rollVal;
  if (deptVal) AcademicStore.student.dept = deptVal;
  if (emailVal) AcademicStore.student.email = emailVal;
  if (mobileVal) AcademicStore.student.mobile = mobileVal;

  try {
    await fetch('/api/update-profile', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        roll_no: AcademicStore.student.roll_no,
        name: nameVal,
        dept: deptVal,
        email: emailVal,
        mobile: mobileVal
      })
    });
  } catch (e) {}

  updateProfileDetails();
  closeEditProfileModal();
  showToast('Profile information saved and synced to MySQL database! ✓', 'success');
}

// ==========================================================================
// 11. TOAST NOTIFICATION SYSTEM
// ==========================================================================
function showToast(message, type = 'info', duration = 3500) {
  const toastContainer = document.getElementById('toast-system');
  if (!toastContainer) return;

  const toast = document.createElement('div');
  toast.className = `toast ${type}`;
  toast.textContent = message;

  toastContainer.appendChild(toast);

  setTimeout(() => {
    toast.style.transition = 'opacity 0.3s ease, transform 0.3s ease';
    toast.style.opacity = '0';
    toast.style.transform = 'translateX(40px)';
    setTimeout(() => {
      if (toast.parentNode) toast.parentNode.removeChild(toast);
    }, 300);
  }, duration);
}

// ==========================================================================
// 12. STRICT ROLE-SEPARATED AUTHENTICATION (STUDENT VS FACULTY TAB LOCK)
// ==========================================================================
let currentAuthTab = 'student';

function setLoginMode(mode) {
  currentAuthTab = mode;

  const roleInput = document.getElementById('login-role');
  if (roleInput) roleInput.value = mode === 'faculty' ? 'faculty' : 'student';

  ['student', 'faculty', 'signup'].forEach(m => {
    const btn = document.getElementById(`pill-tab-${m}`);
    if (btn) btn.classList.toggle('active', m === mode);
  });

  const loginView = document.getElementById('login-view');
  const signupView = document.getElementById('signup-view');
  const idInput = document.getElementById('login-email');
  const pwdInput = document.getElementById('login-password');
  const idLabel = document.getElementById('login-identifier-label');
  const titleText = document.getElementById('login-title-text');
  const subText = document.getElementById('login-sub-text');
  const btnSubmitText = document.getElementById('btn-login-submit-text');

  if (idInput) idInput.value = '';
  if (pwdInput) pwdInput.value = '';

  if (mode === 'signup') {
    if (loginView) loginView.classList.remove('active');
    if (signupView) signupView.classList.add('active');
  } else if (mode === 'faculty') {
    if (signupView) signupView.classList.remove('active');
    if (loginView) loginView.classList.add('active');
    if (titleText) titleText.textContent = 'Faculty & Staff Sign In';
    if (subText) subText.textContent = 'Sign in with your Faculty ID to audit fees and edit student marks';
    if (idLabel) idLabel.textContent = 'Faculty Employee ID';
    if (idInput) {
      idInput.placeholder = 'e.g. STAFF01';
      idInput.removeAttribute('pattern');
      idInput.removeAttribute('maxlength');
    }
    if (btnSubmitText) btnSubmitText.textContent = 'Sign In as Faculty';
  } else {
    if (signupView) signupView.classList.remove('active');
    if (loginView) loginView.classList.add('active');
    if (titleText) titleText.textContent = 'Student Sign In';
    if (subText) subText.textContent = 'Enter your 12-digit Register No and password';
    if (idLabel) idLabel.textContent = '12-Digit Register Number';
    if (idInput) {
      idInput.placeholder = 'e.g. 711522104001';
      idInput.setAttribute('maxlength', '12');
    }
    if (btnSubmitText) btnSubmitText.textContent = 'Sign In to Nexdemy';
  }
}

function calculatePasswordStrength(password) {
  if (!password) return 0;
  let score = 0;
  if (password.length >= 8) score += 25;
  if (/[A-Z]/.test(password)) score += 25;
  if (/[0-9]/.test(password)) score += 25;
  if (/[^A-Za-z0-9]/.test(password)) score += 25;
  return score;
}

function showDashboard(userObj) {
  try {
    const isStaff = userObj.role === 'faculty' || userObj.roll_no === 'STAFF01';

    AcademicStore.student.role = isStaff ? 'faculty' : 'student';
    AcademicStore.student.name = userObj.name || (isStaff ? 'Dr. A. Rajesh (Faculty)' : 'Aravind Kumar S');
    AcademicStore.student.roll_no = userObj.roll_no || (isStaff ? 'STAFF01' : '711522104001');
    AcademicStore.student.dept = userObj.dept || AcademicStore.student.dept;
    AcademicStore.student.email = userObj.email || AcademicStore.student.email;
    AcademicStore.student.mobile = userObj.mobile || AcademicStore.student.mobile;

    document.body.classList.add('dashboard-active');
    document.documentElement.classList.add('dashboard-active');

    const authCard = document.getElementById('auth-container');
    if (authCard) authCard.style.cssText = 'display: none !important;';

    const dash = document.getElementById('dashboard-container');
    if (dash) {
      dash.classList.add('active');
      dash.style.cssText = 'display: block !important; opacity: 1 !important;';
    }

    const navStaff = document.getElementById('nav-item-staff');
    const navHallTicket = document.getElementById('nav-item-hallticket');
    const btnFacultyHeader = document.getElementById('btn-faculty-edit-header');
    const btnHeaderPdf = document.getElementById('btn-header-pdf');
    const facultyActions = document.querySelectorAll('.btn-faculty-action');

    if (isStaff) {
      if (navStaff) navStaff.style.display = 'flex';
      if (navHallTicket) navHallTicket.style.display = 'none'; // Hall ticket sidebar item removed for faculty
      if (btnHeaderPdf) btnHeaderPdf.style.display = 'none'; // Hall ticket (PDF) header button removed for faculty
      if (btnFacultyHeader) btnFacultyHeader.style.display = 'inline-flex';
      facultyActions.forEach(el => el.style.display = 'inline-block');
      switchDashboardTab('staff');
    } else {
      if (navStaff) navStaff.style.display = 'none';
      if (navHallTicket) navHallTicket.style.display = 'flex'; // Hall ticket sidebar item shown for students
      if (btnHeaderPdf) btnHeaderPdf.style.display = 'inline-flex'; // Hall ticket (PDF) header button shown for students
      if (btnFacultyHeader) btnFacultyHeader.style.display = 'none';
      facultyActions.forEach(el => el.style.display = 'none');
      switchDashboardTab('overview');
    }

    updateDashboardUI();

    if (window.monsterEngine && typeof window.monsterEngine.celebrate === 'function') {
      window.monsterEngine.celebrate();
    }

    window.scrollTo(0, 0);
    showToast(`Welcome back, ${AcademicStore.student.name}! 🎓`, 'success', 3500);
  } catch (e) {
    console.error('showDashboard error:', e);
  }
}

function handleLogout() {
  const dash = document.getElementById('dashboard-container');
  if (dash) {
    dash.classList.remove('active');
    dash.style.cssText = 'display: none !important;';
  }

  document.body.classList.remove('dashboard-active');
  document.documentElement.classList.remove('dashboard-active');

  const authCard = document.getElementById('auth-container');
  if (authCard) authCard.style.cssText = 'display: flex !important; opacity: 1 !important;';

  const emailInput = document.getElementById('login-email');
  const pwdInput = document.getElementById('login-password');
  if (emailInput) emailInput.value = '';
  if (pwdInput) pwdInput.value = '';

  if (window.monsterEngine && typeof window.monsterEngine.replayToyDrop === 'function') {
    window.monsterEngine.replayToyDrop();
  }

  showToast('Signed out from Nexdemy Portal.', 'info');
}

function switchDashboardTab(tabKey) {
  if (!tabKey) return;

  // If faculty tries to open hallticket tab, redirect to staff
  if (AcademicStore.student.role === 'faculty' && tabKey === 'hallticket') {
    tabKey = 'staff';
  }

  document.querySelectorAll('.sidebar-nav .nav-item').forEach(nav => {
    if (nav.getAttribute('data-tab') === tabKey) nav.classList.add('active');
    else nav.classList.remove('active');
  });

  document.querySelectorAll('.dash-tab-pane').forEach(pane => pane.classList.remove('active'));
  document.getElementById('tab-' + tabKey)?.classList.add('active');

  const isStaff = AcademicStore.student.role === 'faculty';

  const titles = {
    overview: { 
      title: isStaff ? 'Class Academic Overview (Enrolled Students Average)' : 'Academic Overview', 
      subtitle: isStaff ? 'Class performance metrics, attendance telemetry & averages across enrolled students' : 'Nexdemy Academic Portal | 2024-2025 Semester 4' 
    },
    courses: { 
      title: 'Semester 4 Core Curriculum & Faculty Directory', 
      subtitle: 'Nexdemy Academic Portal | Syllabus, internal test performance & attendance' 
    },
    attendance: { 
      title: isStaff ? 'Class-Wide Attendance Gauge & Telemetry (Enrolled Students Average)' : 'Compliance Attendance Gauge & Telemetry', 
      subtitle: isStaff ? `Overall class average: ${calculateOverallAttendance().percentage}% • Minimum 75.0% threshold compliance roster` : 'Nexdemy Academic Regulation: Minimum 75.0% required for exam eligibility' 
    },
    marks: { 
      title: isStaff ? 'Class Marks & CGPA Evaluation Matrix (Enrolled Students Average)' : 'Internal Marks & CGPA Calculator with What-If Simulator', 
      subtitle: isStaff ? `Class average CGPA: ${calculateCGPA().cgpa.toFixed(2)} / 10.0 • Individual student score cards` : 'Academic evaluation matrix, letter grade classifications & scenario projections' 
    },
    timetable: { 
      title: 'Interactive Weekly Class Timetable Matrix', 
      subtitle: '6 periods daily schedule with morning tea break and lunch interval' 
    },
    fees: { 
      title: isStaff ? 'Class Tuition Fee Audit Ledger (Enrolled Students Summary)' : 'Semester Fee Status & Transaction Audit Ledger', 
      subtitle: isStaff ? `Class fee audit: ${FacultyStore.students.filter(s => s.fee_status === 'Paid').length}/${FacultyStore.students.length} students cleared` : 'Nexdemy — Official student payment transaction audit trail' 
    },
    hallticket: { 
      title: 'End-Semester Examination Hall Ticket & Vector PDF', 
      subtitle: 'Official admit card compilation and direct PDF download' 
    },
    profile: { 
      title: isStaff ? 'Faculty Advisor Profile & Credentials' : 'Student Profile & Academic Records', 
      subtitle: 'Nexdemy verified institutional registration and personal contact details' 
    },
    staff: { 
      title: 'Faculty & Staff Academic Evaluation Portal', 
      subtitle: 'Class Roster Management, CGPA & Marks Editing, Fee Audits & Student Registration' 
    }
  };

  if (titles[tabKey]) {
    const headingEl = document.getElementById('dash-page-title');
    const subEl = document.getElementById('dash-page-subtitle');
    if (headingEl) headingEl.textContent = titles[tabKey].title;
    if (subEl) subEl.textContent = titles[tabKey].subtitle;
  }
}

// ==========================================================================
// 13. AUTH SETUP & STRICT TAB ENFORCEMENT
// ==========================================================================
function setupAuthForms() {
  document.getElementById('login-form')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    const idVal = document.getElementById('login-email') ? document.getElementById('login-email').value.trim() : '';
    const pwdVal = document.getElementById('login-password') ? document.getElementById('login-password').value.trim() : '';
    const activeRole = currentAuthTab === 'faculty' ? 'faculty' : 'student';

    if (!idVal) {
      showToast(activeRole === 'faculty' ? 'Please enter your Faculty ID.' : 'Please enter your 12-digit Register No.', 'warning');
      return;
    }

    if (!pwdVal) {
      showToast('Please enter your password.', 'warning');
      return;
    }

    if (activeRole === 'student' && (idVal.toUpperCase() === 'STAFF01' || idVal.toUpperCase().startsWith('STAFF'))) {
      showToast('Access Denied: Faculty accounts must sign in using the "Faculty Sign In" tab.', 'warning', 4500);
      return;
    }

    if (activeRole === 'faculty' && (/^\d{12}$/.test(idVal) || (idVal.includes('@nexdemy.edu') && !idVal.includes('staff')))) {
      showToast('Access Denied: Student accounts must sign in using the "Student Sign In" tab.', 'warning', 4500);
      return;
    }

    try {
      const response = await fetch('/api/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ identifier: idVal, password: pwdVal, role: activeRole })
      });

      const data = await response.json();

      if (data.success && data.user) {
        showDashboard(data.user);
      } else {
        showToast(data.message || 'Access Denied: Invalid credentials or incorrect tab.', 'warning', 4500);
      }
    } catch (err) {
      if (activeRole === 'faculty' && idVal.toUpperCase() === 'STAFF01' && pwdVal === 'Staff@2026') {
        showDashboard({ name: 'Dr. A. Rajesh (Faculty)', roll_no: 'STAFF01', role: 'faculty' });
      } else if (activeRole === 'student' && idVal === '711522104001' && pwdVal === 'Student@2026') {
        showDashboard({ name: 'Aravind Kumar S', roll_no: '711522104001', role: 'student' });
      } else {
        showToast('Access Denied: Account not registered or incorrect tab/password.', 'warning', 4500);
      }
    }
  });

  document.getElementById('signup-form')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    const nameVal = document.getElementById('signup-name')?.value.trim();
    const rollVal = document.getElementById('signup-roll')?.value.trim();
    const deptVal = document.getElementById('signup-dept')?.value;
    const emailVal = document.getElementById('signup-email')?.value.trim();
    const mobileVal = document.getElementById('signup-mobile')?.value.trim();
    const pwdVal = document.getElementById('signup-password')?.value.trim();

    if (!nameVal) {
      showToast('Please enter your full student name.', 'warning');
      return;
    }

    if (!rollVal || rollVal.length !== 12 || !/^\d{12}$/.test(rollVal)) {
      showToast('Register Number must be exactly 12 digits (e.g. 711522104001).', 'warning');
      return;
    }

    if (!deptVal) {
      showToast('Please select your department from the dropdown.', 'warning');
      return;
    }

    if (!pwdVal || pwdVal.length < 6) {
      showToast('Password must be at least 6 characters.', 'warning');
      return;
    }

    const newUserPayload = {
      name: nameVal,
      roll_no: rollVal,
      dept: deptVal,
      email: emailVal,
      mobile: mobileVal,
      password: pwdVal,
      role: 'student'
    };

    try {
      const response = await fetch('/api/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newUserPayload)
      });

      const data = await response.json();

      if (data.success && data.user) {
        showDashboard(data.user);
      } else {
        showToast(data.message || 'Registration error. Please verify your details.', 'warning', 4500);
      }
    } catch (err) {
      showDashboard(newUserPayload);
    }
  });

  const loginPwdInput = document.getElementById('login-password');
  const signupPwdInput = document.getElementById('signup-password');
  const loginToggle = document.getElementById('login-toggle-pwd');
  const signupToggle = document.getElementById('signup-toggle-pwd');

  function setupPasswordToggle(input, button) {
    if (!input || !button) return;
    button.addEventListener('click', () => {
      const isPwd = input.getAttribute('type') === 'password';
      input.setAttribute('type', isPwd ? 'text' : 'password');
      button.classList.toggle('show-pwd', isPwd);

      if (window.monsterEngine && typeof window.monsterEngine.setPasswordMode === 'function') {
        window.monsterEngine.setPasswordMode(true, isPwd);
      }
    });

    input.addEventListener('focus', () => {
      const isVisible = input.getAttribute('type') === 'text';
      if (window.monsterEngine && typeof window.monsterEngine.setPasswordMode === 'function') {
        window.monsterEngine.setPasswordMode(true, isVisible);
      }
    });

    input.addEventListener('blur', () => {
      if (window.monsterEngine && typeof window.monsterEngine.setPasswordMode === 'function') {
        window.monsterEngine.setPasswordMode(false, false);
      }
    });
  }

  setupPasswordToggle(loginPwdInput, loginToggle);
  setupPasswordToggle(signupPwdInput, signupToggle);

  const inputsToTrack = ['login-email', 'signup-name', 'signup-roll', 'signup-email', 'signup-mobile', 'forgot-identifier', 'forgot-target-email', 'forgot-otp-code', 'add-stu-roll', 'add-stu-name'];
  inputsToTrack.forEach(id => {
    const el = document.getElementById(id);
    if (!el) return;
    el.addEventListener('focus', () => {
      if (window.monsterEngine && typeof window.monsterEngine.setInputFocus === 'function') {
        window.monsterEngine.setInputFocus(true, el);
      }
    });
    el.addEventListener('blur', () => {
      if (window.monsterEngine && typeof window.monsterEngine.setInputFocus === 'function') {
        window.monsterEngine.setInputFocus(false, null);
      }
    });
    el.addEventListener('input', () => {
      if (window.monsterEngine && typeof window.monsterEngine.triggerKeystrokeImpulse === 'function') {
        window.monsterEngine.triggerKeystrokeImpulse();
      }
    });
  });

  if (signupPwdInput) {
    const bar = document.getElementById('strength-bar');
    const lbl = document.getElementById('strength-label');
    signupPwdInput.addEventListener('input', () => {
      const score = calculatePasswordStrength(signupPwdInput.value);
      if (bar) {
        bar.style.width = score + '%';
        if (score < 50) bar.style.backgroundColor = '#ef4444';
        else if (score < 75) bar.style.backgroundColor = '#f59e0b';
        else bar.style.backgroundColor = '#10b981';
      }
      if (lbl) {
        if (score === 0) lbl.textContent = 'Password strength';
        else if (score < 50) lbl.textContent = 'Weak password';
        else if (score < 75) lbl.textContent = 'Medium strength';
        else lbl.textContent = 'Strong password ✓';
      }
    });
  }
}

// ==========================================================================
// 14. APP INITIALIZATION
// ==========================================================================
document.addEventListener('DOMContentLoaded', () => {
  setupAuthForms();
  setLoginMode('student');
});
